/* the first trap's spectra: carrier 8 V at 1000 kHz and sidebands of sbV volts, to scale (18 px per volt) */
function CM_trapSpec(sbV,col,label){const y0=262,k=18,xf=f=>320+(f-1000)*26;return CM_L(30,y0,610,y0,CM_GRY,2)+CM_line(xf(1000),y0,8*k,BLU)+CM_T(xf(1000)+16,y0-8*k+8,'8 V',{fs:22,fw:800,fill:BLU})+CM_line(xf(995),y0,sbV*k,col)+CM_line(xf(1005),y0,sbV*k,col)+CM_T(xf(995),y0-sbV*k-18,`${sbV} V`,{fs:24,fw:800,a:'middle',fill:col})+CM_T(xf(1005),y0-sbV*k-18,`${sbV} V`,{fs:24,fw:800,a:'middle',fill:col})+[995,1000,1005].map(f=>CM_T(xf(f),y0+30,String(f),{fs:22,a:'middle',fill:CM_MUT})).join('')+CM_T(610,y0+30,'kHz',{fs:22,a:'end',fill:CM_MUT})+CM_T(20,44,label,{fs:24,fw:800,fill:col})}
/* the second trap's axes: detector output amplitude (V) against phase error φ (degrees), 0 to 90 */
function CM_phx(p){return 90+p*5.4}
function CM_phy(v){return 262-v*20}
function CM_phiAxes(){return CM_L(CM_phx(0),262,CM_phx(90)+20,262,CM_GRY,2)+CM_L(CM_phx(0),262,CM_phx(0),40,CM_GRY,2)+[0,30,60,90].map(p=>CM_L(CM_phx(p),262,CM_phx(p),270,CM_MUT,2)+CM_T(CM_phx(p),296,p+'°',{fs:22,a:'middle',fill:CM_MUT})).join('')+[[10,'10'],[5,'5']].map(([v,t])=>CM_L(CM_phx(0)-8,CM_phy(v),CM_phx(0),CM_phy(v),CM_MUT,2)+CM_T(CM_phx(0)-14,CM_phy(v)+8,t,{fs:22,a:'end',fill:CM_MUT})).join('')+CM_T(CM_phx(0)-14,30,'V',{fs:22,a:'end',fill:CM_MUT})+CM_T(610,322,'phase error φ',{fs:22,a:'end',fill:CM_MUT})}
function EXTRA(R,ICON){
 /* hook: the AM spectrum at m = 1 (carrier Ac, sidebands Ac/2) and the power split 2/3 : 1/3 */
 ICON.cmHookSpec=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CM_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${CM_L(30,136,350,136,CM_GRY,2)}${CM_line(190,136,80,ORG)}${CM_line(70,136,40,GRN)}${CM_line(310,136,40,GRN)}${CM_T(190,40,'carrier: no message',{fs:22,fw:800,a:'middle',fill:ORG})}${CM_T(70,84,'message',{fs:22,fw:800,a:'middle',fill:GRN})}${CM_T(310,84,'message',{fs:22,fw:800,a:'middle',fill:GRN})}</g>`;
 ICON.cmHookBar=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CM_box(0,0,380,160,{fill:'#FFFFFF',st:GRN,sw:3,r:18})}${CM_T(20,40,'power at m = 1',{fs:24,fw:800})}<rect x="20" y="62" width="${(340*2/3).toFixed(1)}" height="60" rx="8" fill="${ORG}"/><rect x="${(20+340*2/3).toFixed(1)}" y="62" width="${(340/3).toFixed(1)}" height="60" rx="8" fill="${GRN}"/>${CM_T(36,101,'carrier 2/3',{fs:24,fw:800,fill:'#FFFFFF'})}${CM_T(20+340*5/6,101,'1/3',{fs:24,fw:800,a:'middle',fill:'#FFFFFF'})}${CM_T(360,150,'sidebands',{fs:22,fw:700,a:'end',fill:GRN})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.cmRecAM=(x,y)=>{const y0=230,k=14,xf=f=>210+(f-1000)*32;return `<g transform="translate(${x-210} ${y-165})">${CM_curve(t=>(1+0.5*Math.cos(2*Math.PI*t))*Math.cos(2*Math.PI*10*t),0,1.5,10,410,48,24,BLU,2.5,500)}${CM_L(0,y0,420,y0,CM_GRY,2)}${CM_line(xf(1000),y0,8*k,BLU)}${CM_line(xf(995),y0,2*k,ORG)}${CM_line(xf(1005),y0,2*k,ORG)}${CM_T(xf(1000)+14,y0-8*k+30,'8 V',{fs:24,fw:800,fill:BLU})}${CM_T(xf(995),y0-2*k-14,'2 V',{fs:24,fw:800,a:'middle',fill:ORG})}${CM_T(xf(1005),y0-2*k-14,'2 V',{fs:24,fw:800,a:'middle',fill:ORG})}${[995,1000,1005].map(f=>CM_T(xf(f),y0+32,String(f),{fs:22,a:'middle',fill:CM_MUT})).join('')}${CM_T(210,y0+72,'B = 10 kHz',{fs:26,fw:800,a:'middle'})}</g>`};
 ICON.cmRecPow=(x,y)=>{const mx=m=>40+m*340,ey=e=>270-e*600,eta=m=>m*m/(2+m*m);return `<g transform="translate(${x-210} ${y-165})">${CM_L(40,270,400,270,CM_GRY,2)}${CM_L(40,270,40,40,CM_GRY,2)}${CM_curve(eta,0,1,mx(0),mx(1),270,600,ORG,5,100)}<circle cx="${mx(1)}" cy="${ey(eta(1)).toFixed(1)}" r="9" fill="${ORG}"/><circle cx="${mx(0.5)}" cy="${ey(eta(0.5)).toFixed(1)}" r="9" fill="${ORG}"/>${CM_T(mx(1),ey(eta(1))-20,'33.3 %',{fs:24,fw:800,a:'end',fill:ORG})}${CM_T(mx(0.5)+18,ey(eta(0.5))+34,'11.1 %',{fs:24,fw:800,fill:ORG})}${[0,0.5,1].map(m=>CM_T(mx(m),300,String(m),{fs:22,a:'middle',fill:CM_MUT})).join('')}${CM_T(410,330,'m',{fs:24,fw:800,a:'end',fill:CM_MUT})}${CM_T(56,60,'η = m²/(2 + m²)',{fs:26,fw:800})}</g>`};
 ICON.cmRecDSB=(x,y)=>{const y0=230,k=14,xf=f=>210+(f-100)*120;return `<g transform="translate(${x-210} ${y-165})">${CM_L(0,y0,420,y0,CM_GRY,2)}${CM_line(xf(99),y0,10*k,GRN)}${CM_line(xf(101),y0,10*k,GRN)}${CM_L(xf(100),y0,xf(100),y0-110,CM_MUT,2,'stroke-dasharray="6 6"')}${CM_T(xf(100),y0-124,'no carrier',{fs:22,fw:700,a:'middle',fill:CM_MUT})}${CM_T(xf(99),y0-10*k-18,'10 V',{fs:24,fw:800,a:'middle',fill:GRN})}${CM_T(xf(101),y0-10*k-18,'10 V',{fs:24,fw:800,a:'middle',fill:GRN})}${[99,100,101].map(f=>CM_T(xf(f),y0+32,String(f),{fs:22,a:'middle',fill:CM_MUT})).join('')}${CM_T(210,y0+72,'2 W, not 6 W',{fs:26,fw:800,a:'middle'})}</g>`};
}
